namespace py = pybind11;
using namespace galbot::sdk;
using namespace pybind11::literals;

// ------------------ Python 绑定 ------------------
PYBIND11_MODULE(galbot_sdk, m) {
  m.doc() = "Python bindings for GALBOT SDK";

  // ------------------ Motion Plan ------------------
  bindPlnnerType(m);
  bindMotionPlanConfig(m);
  bindPlnnerInterface(m);

  // ------------------ GalbotRobot ------------------
  bind_robot_type(m);
  bind_basic_interface(m);

  // ------------------ GalbotNavigation ------------------
  bind_galbot_navigation(m);

  // ------------------ GalbotPerception ------------------
  bind_galbot_perception(m);

  // 进程退出兜底（Python 侧双保险）。C++ 层已在每个 EmbosaInit 调用点注册了
  // std::atexit 守卫；这里再注册一个 Python atexit，使 embosa::Clear() 在
  // Python 解释器关停阶段（早于 C++ 静态析构）就被调用，这是最安全的时机。
  // 守卫内部 std::call_once 保证幂等，两条路径谁先执行都安全，另一条自动 no-op。
  // 注意：用匿名 cpp_function 直接注册给 atexit，不在模块上暴露命名属性，
  // 避免该内部函数泄漏到 .pyi stub 和对外 API 文档。
  py::module_::import("atexit").attr("register")(
      py::cpp_function([] { galbot::sdk::run_embosa_exit_guard(); }));
}

