class WBCException : public std::exception {
   public:
    WBCException(const std::string& msg) : msg_(msg) {}
    const char* what() const noexcept override { return msg_.c_str(); }

   private:
    std::string msg_;
};

//------------- Sensor convert function---------

template <typename T>
py::array_t<T> repeated_to_numpy(const google::protobuf::RepeatedField<T>& field) {
    return py::array_t<T>({field.size()}, {sizeof(T)}, field.data());
}

inline py::dict convert_header(const Header& header) {
    return py::dict("frame_id"_a = header.frame_id, "timestamp_ns"_a = header.timestamp_ns);
}
inline py::dict convert_header(const galbot::core_proto::Header& header) {
    return py::dict(
        "frame_id"_a = header.frame_id(),
        "timestamp"_a = py::dict("sec"_a = header.timestamp().sec(), "nanosec"_a = header.timestamp().nanosec()));
}

inline py::dict convert_roi(const galbot::sensor_proto::RegionOfInterest& roi) {
    return py::dict("x_offset"_a = roi.x_offset(), "y_offset"_a = roi.y_offset(), "height"_a = roi.height(),
                    "width"_a = roi.width(), "do_rectify"_a = roi.do_rectify());
}

py::dict convert_imu_data(const std::shared_ptr<ImuData> imu_data_ptr) {
    py::dict result;
    if (!imu_data_ptr) {
        return result;
    }
    result["timestamp_ns"] = imu_data_ptr->timestamp_ns;

    // 假设 Vector3 有 x, y, z
    result["accel"] =
        py::dict("x"_a = imu_data_ptr->accel.x, "y"_a = imu_data_ptr->accel.y, "z"_a = imu_data_ptr->accel.z);

    result["gyro"] = py::dict("x"_a = imu_data_ptr->gyro.x, "y"_a = imu_data_ptr->gyro.y, "z"_a = imu_data_ptr->gyro.z);

    result["magnet"] =
        py::dict("x"_a = imu_data_ptr->magnet.x, "y"_a = imu_data_ptr->magnet.y, "z"_a = imu_data_ptr->magnet.z);

    return result;
}

py::dict convert_device_info(const std::shared_ptr<DeviceInfo> device_info_ptr) {
    py::dict result;
    if (!device_info_ptr) {
        return result;
    }
    result["model"] = device_info_ptr->model;
    result["serial_number"] = device_info_ptr->serial_number;
    result["firmware_version"] = device_info_ptr->firmware_version;
    result["hardware_version"] = device_info_ptr->hardware_version;
    result["manufacturer"] = device_info_ptr->manufacturer;

    return result;
}

py::dict convert_odom_data(const std::shared_ptr<OdomData> odom_data_ptr) {
    py::dict result;
    if (!odom_data_ptr) {
        return result;
    }
    result["timestamp_ns"] = odom_data_ptr->timestamp_ns;

    // 转换位置数组 [x, y, z]
    result["position"] = py::cast(odom_data_ptr->position);

    // 转换姿态四元数 [x, y, z, w]
    result["orientation"] = py::cast(odom_data_ptr->orientation);


